// Verbatim port of monster_homebrew.html inline script wrapped for the SPA — regenerated by
// scripts/wrap_p5_js.py; edit the generator, not this file.
import { exposeGlobals, unexposeGlobals } from '../../../lib/legacy.js';

export function init(ctx, d, G) {
  let _dead = false;
  void d;
  // {key: {label, topdown: [...], portrait: [...]}} — art direction per genre
  const _ICON_GENRES = G.ICON_GENRES;
  const _SIZE_SQUARES = {tiny: 1, small: 1, medium: 1, large: 2, huge: 3, gargantuan: 4};

  let _iconView = 'topdown';

  // ── Kind selector (Monster / Ship & Vehicle / Other Asset) ────────────────────
  // Writes to the Type field (unless the user typed their own), swaps the
  // hint placeholders, and picks the matching Icon Prompt framing.

  const _HB_KINDS = {
    monster: { autoType: '',        typePh: 'beast, undead…',
               notesPh: 'Describe traits, actions, reactions…', icon: 'portrait' },
    vehicle: { autoType: 'vehicle', typePh: 'vehicle — sailing ship, war rig…',
               notesPh: 'Describe weapons, crew, speed, cargo…', icon: 'topdown' },
    asset:   { autoType: 'object',  typePh: 'object — siege engine, caravan, artifact…',
               notesPh: 'Describe what it does and how it can be interacted with…', icon: 'topdown' },
  };
  let _hbKind = 'monster';

  function setHbKind(kind) {
    const prev = _HB_KINDS[_hbKind], next = _HB_KINDS[kind];
    _hbKind = kind;
    ['monster', 'vehicle', 'asset'].forEach(k => {
      const b = document.getElementById('hb-kind-' + k);
      if (k === kind) { b.style.background = 'var(--ttrpg-accent)'; b.style.color = 'var(--sp-on-accent)'; b.style.border = 'none'; }
      else { b.style.background = 'var(--ttrpg-surface)'; b.style.color = 'var(--ttrpg-text)'; b.style.border = '1px solid var(--sp-border)'; }
    });
    const typeEl  = document.querySelector('[name="monster_type"]');
    const notesEl = document.querySelector('[name="notes"]');
    // only overwrite Type when it's empty or still holds a previous auto value
    if (!typeEl.value.trim() || typeEl.value.trim() === prev.autoType) {
      typeEl.value = next.autoType;
    }
    typeEl.placeholder  = next.typePh;
    notesEl.placeholder = next.notesPh;
    setIconView(next.icon);
  }

  // Edit mode: infer the kind from the stored type
  (() => {
    const t = (document.querySelector('[name="monster_type"]').value || '').toLowerCase();
    if (/vehicle|ship|boat|rig|craft|shuttle/.test(t)) setHbKind('vehicle');
    else if (/object|asset|structure|item/.test(t))    setHbKind('asset');
    else setHbKind('monster');
  })();

  // ── Randomize: server rolls a full entry for the current kind/genre/tier ──────
  async function randomizeHomebrew() {
    const btn = document.getElementById('hb-random-btn');
    btn.disabled = true;
    const genre = document.getElementById('hb-genre').value;
    try {
      const r = await fetch(`/ttrpg/monsters/homebrew/random?kind=${_hbKind}` +
                            `&genre=${encodeURIComponent(genre)}` +
                            `&tier=${document.getElementById('hb-tier').value}`);
      const d = await r.json();
      const set = (name, v) => {
        const el = document.querySelector(`[name="${name}"]`);
        if (el && v !== undefined && v !== null) el.value = v;
      };
      ['name', 'monster_type', 'size', 'alignment', 'speed', 'cr', 'xp',
       'hp_max', 'ac', 'languages', 'notes',
       'str_val', 'dex_val', 'con_val', 'int_val', 'wis_val', 'cha_val']
        .forEach(f => set(f, d[f]));
      // keep the icon-prompt genre in step so the token art matches
      const icpGenre = document.getElementById('icp-genre');
      if (icpGenre) icpGenre.value = genre;
    } catch (err) {
      console.error('Randomize failed:', err);
    }
    btn.disabled = false;
  }

  function setIconView(view) {
    _iconView = view;
    const td = document.getElementById('icp-topdown-btn');
    const pt = document.getElementById('icp-portrait-btn');
    const accent = 'var(--ttrpg-accent)', surface = 'var(--ttrpg-surface)', text = 'var(--ttrpg-text)';
    const on  = b => { b.style.background = accent;  b.style.color = 'var(--sp-on-accent)'; b.style.border = 'none'; };
    const off = b => { b.style.background = surface; b.style.color = text; b.style.border = '1px solid var(--sp-border)'; };
    if (view === 'topdown') { on(td); off(pt); } else { on(pt); off(td); }
  }

  function openIconPrompt() {
    document.getElementById('icp-output-section').style.display = 'none';
    new bootstrap.Modal(document.getElementById('iconPromptModal')).show();
  }

  function _fv(name) {
    const el = document.querySelector('[name="' + name + '"]');
    return el ? el.value.trim() : '';
  }

  function generateIconPrompt() {
    const name     = _fv('name') || 'the subject';
    const type     = _fv('monster_type');
    const size     = _fv('size') || 'Medium';
    const notes    = _fv('notes');
    const freetext = document.getElementById('icp-freetext').value.trim();
    const genreKey = document.getElementById('icp-genre').value;
    const genre    = _ICON_GENRES[genreKey] || _ICON_GENRES.fantasy;
    const squares  = _SIZE_SQUARES[size.toLowerCase()] || 1;
    const topdown  = _iconView === 'topdown';

    const lines = [];
    if (topdown) {
      lines.push('Please generate a TOP-DOWN game token image for use on a TTRPG map.\n');
    } else {
      lines.push('Please generate a creature token portrait for use on a TTRPG map.\n');
    }

    lines.push('## SUBJECT');
    lines.push('Name: ' + name);
    if (type) lines.push('Type: ' + type);
    lines.push('Size: ' + size + ' — occupies ' + squares + '×' + squares + ' grid square' + (squares > 1 ? 's' : '') + ' on the map');
    if (genreKey !== 'fantasy') lines.push('Setting: ' + genre.label + ' — not medieval fantasy.');
    if (notes)    lines.push('Description: ' + notes);
    if (freetext) lines.push('Details: ' + freetext);
    lines.push('');

    lines.push('## TOKEN REQUIREMENTS (CRITICAL)');
    if (topdown) {
      lines.push('- Viewed from DIRECTLY ABOVE (plan view), as if seen from the sky or orbit — no isometric or side angle.');
      lines.push('- Front / bow pointing straight toward the TOP of the image, so rotation reads naturally on a grid.');
      lines.push('- One single subject, centered, filling about 90% of the frame.');
      lines.push('- Plain solid dark background (or transparent if supported) — NO scenery, water, or ground texture; the map underneath provides the terrain.');
      lines.push('- Lighting from directly overhead; at most a soft shadow directly beneath the subject.');
    } else {
      lines.push('- A single creature, centered, filling most of the frame — head and upper body prominent.');
      lines.push('- Plain, softly darkened background — no scenery that will clash with the map or clutter a small token.');
      lines.push('- Strong silhouette and clear focal face/features.');
    }
    lines.push('- The image must stay readable when shrunk to a small round/square token on a game grid.');
    lines.push('- No text, numbers, labels, borders, or watermarks anywhere in the image.');
    lines.push('');

    lines.push('## ART DIRECTION');
    (topdown ? genre.topdown : genre.portrait).forEach(f => lines.push('- ' + f));

    document.getElementById('icp-text').value = lines.join('\n');
    document.getElementById('icp-output-section').style.display = '';
  }

  // Gemini one-click token: uses the prompt exactly as shown, drops the image
  // into the form's Picture input — it saves with the entry like an upload.
  function aiGenerateIcon(btn) {
    const status = document.getElementById('icp-ai-status');
    const input = document.querySelector('input[type="file"][name="image"]');
    if (!input) return;
    if (!document.getElementById('icp-text').value.trim()) generateIconPrompt();
    const prompt = document.getElementById('icp-text').value;
    const orig = btn.innerHTML;
    btn.disabled = true;
    btn.textContent = '✨ Painting…';
    status.textContent = '';
    status.style.color = '';
    aiImageWithPreview(() => aiImageBlob(prompt),
                       { title: 'Token preview', useLabel: 'Use as token',
                         onRegenerate: () => { status.textContent = '✨ Painting another…'; } })
      .then(blob => {
        if (!blob) { status.textContent = 'Discarded — nothing attached.'; return; }
        aiBlobToFileInput(blob, input, 'token');
        status.textContent =
          '✨ Token attached to the Picture field — it saves with the entry.';
      })
      .catch(e => {
        status.textContent = 'AI: ' + e.message;
        status.style.color = 'var(--bs-danger, #dc3545)';
      })
      .finally(() => { btn.disabled = false; btn.innerHTML = orig; });
  }
  (() => {
    if (typeof aiConfigured === 'function') {
      aiConfigured().then(on => {
        const b = document.getElementById('icp-ai-btn');
        if (b && on) { b.style.display = ''; aiBrandImageButton(b); }
      });
    }
  })();

  function copyIconPrompt() {
    const ta = document.getElementById('icp-text');
    const fb = document.getElementById('icp-copy-fb');
    function showFb() { fb.style.display = ''; setTimeout(() => { fb.style.display = 'none'; }, 2000); }
    // The async clipboard API only exists in secure contexts — on the LAN's
    // plain-http address navigator.clipboard is undefined, so the legacy
    // select-and-copy path must be a real branch, not just a .catch().
    function legacyCopy() {
      ta.removeAttribute('readonly');
      ta.focus();
      ta.select();
      ta.setSelectionRange(0, ta.value.length);
      let ok = false;
      try { ok = document.execCommand('copy'); } catch (e) {}
      ta.setAttribute('readonly', '');
      if (ok) { showFb(); return; }
      // Last resort: the text is left selected — say what to do with it.
      fb.textContent = 'Press Ctrl+C to copy';
      fb.style.display = '';
      setTimeout(() => { fb.style.display = 'none'; fb.textContent = 'Copied!'; }, 3500);
    }
    if (navigator.clipboard && navigator.clipboard.writeText && window.isSecureContext) {
      navigator.clipboard.writeText(ta.value).then(showFb).catch(legacyCopy);
    } else {
      legacyCopy();
    }
  }

  const NAMES = ["setHbKind", "randomizeHomebrew", "setIconView", "openIconPrompt", "_fv", "generateIconPrompt", "aiGenerateIcon", "copyIconPrompt"];
  exposeGlobals({ setHbKind, randomizeHomebrew, setIconView, openIconPrompt, _fv, generateIconPrompt, aiGenerateIcon, copyIconPrompt });
  return () => {
    _dead = true;

    unexposeGlobals(NAMES);
  };
}
